window.TADABBUR_ARAF = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة الأعراف (٧)، سورةٌ مكّيّةٌ في التوحيد وقصصِ الأنبياء. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، والنصُّ القرآنيُّ يُؤخذ من المورفولوجيا وقتَ العرض."},"n":7,"name":"الأعراف","total_ayahs":206,"audio":[],"passages":[{"title":"الكتابُ المنذر، وميزانُ يوم القيامة","range":[1,10],"theme":"اتّباعُ الوحي وحده، والاعتبارُ بإهلاك القرى، وأنّ الوزنَ يومئذٍ بالحقّ","verses":[{"n":1,"reflection":{"text":"«المص» — حروفٌ مقطّعةٌ في أوائل بعض السور، أسلمُ الأقوال فيها التوقّفُ عن تعيين المراد وأنّ الله أعلمُ بمرادها؛ وفيها تنبيهٌ على إعجاز القرآن المبنيِّ من جنس هذه الحروف التي يعرفها العرب، ومع ذلك عجزوا عن معارضته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله فيما استأثر بعلمه، وتعظيمُ كلامه."},"action":{"text":"قِف عند حدّ علمك، ولا تتكلّف تأويلَ ما لم يُبيَّن لك، وعظّم القرآن."}},{"n":2,"reflection":{"text":"«كتاب أنزل إليك فلا يكن في صدرك حرج منه لتنذر به وذكرى للمؤمنين» — هذا القرآنُ كتابٌ أنزله الله إليك؛ فلا يكن في صدرك ضيقٌ من تبليغه خوفَ تكذيبهم؛ أُنزل لتنذر به الكافرين وتذكّر به المؤمنين. فبلّغه بصدرٍ منشرحٍ لا حرجَ فيه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"انشراحُ الصدرِ بتبليغِ الحقّ بلا حرج."},"action":{"text":"بلّغ الحقَّ الذي تعلمه بلا تردّدٍ ولا ضيق، فهو إنذارٌ وذكرى."}},{"n":3,"reflection":{"text":"«اتبعوا ما أنزل إليكم من ربكم ولا تتبعوا من دونه أولياء قليلا ما تذكرون» — اتّبعوا القرآنَ والسنّةَ المنزّلَين من ربّكم، ولا تتّبعوا من دون الله أولياءَ من شياطينَ أو أحبارٍ تُطيعونهم في مخالفة الوحي؛ قليلًا ما تتّعظون؛ فالمتبوعُ الحقُّ هو الوحيُ وحده. فلا متبوعَ في الدين إلا ما أنزل الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الوحي وحده وتركُ الأولياءِ من دونه."},"action":{"text":"اتّبع كتابَ الله وسنّةَ رسوله، ولا تُقدّم عليهما قولَ أحدٍ كائنًا من كان."}},{"n":4,"reflection":{"text":"«وكم من قرية أهلكناها فجاءها بأسنا بياتا أو هم قائلون» — وكثيرٌ من القرى الظالمة أهلكناها، فجاءها عذابُنا ليلًا وهم نائمون، أو نهارًا وقتَ القيلولة؛ فأخذهم العذابُ في حال غفلةٍ وأمن؛ فلا يأمن أحدٌ مكرَ الله. فبأسُ الله يأتي بغتةً في وقت الأمن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الأمنِ من مكرِ الله مع الإصرارِ على الظلم."},"action":{"text":"لا تأمن عقوبةَ الله وأنت مقيمٌ على ذنب، فبأسُه يأتي بغتةً في غفلة."}},{"n":5,"reflection":{"text":"«فما كان دعواهم إذ جاءهم بأسنا إلا أن قالوا إنا كنا ظالمين» — فما كان قولُهم حين نزل العذابُ إلا الاعترافَ: إنّا كنّا ظالمين؛ أقرّوا بظلمهم حين لا ينفع الإقرار. فالاعترافُ ينفع قبل نزول العذاب لا بعده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعترافُ بالتقصيرِ والتوبةُ قبل فواتِ الأوان."},"action":{"text":"اعترف بذنبك وتُب الآن حيث ينفع، لا حين ينزل البأسُ فلا ينفع الندم."}},{"n":6,"reflection":{"text":"«فلنسألن الذين أرسل إليهم ولنسألن المرسلين» — فلنسألنّ الأممَ الذين أُرسل إليهم الرسل: ماذا أجبتم؟ ولنسألنّ الرسلَ: هل بلّغتم؟ فيُسأل الجميعُ يومَ القيامة عن التبليغ والاستجابة. فكلٌّ مسؤولٌ: المبلِّغُ والمبلَّغ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للسؤالِ يومَ القيامةِ عن الاستجابة."},"action":{"text":"استعدّ لسؤال الله لك عمّا بلغك من الحقّ، فماذا أنت صانعٌ به؟"}},{"n":7,"reflection":{"text":"«فلنقصن عليهم بعلم وما كنا غائبين» — فلنخبرنّ الرسلَ والأممَ بأعمالهم عن علمٍ تامٍّ أحاط بكلّ شيء، فما كنّا غائبين عنهم طرفةَ عين بل شاهدنا أعمالهم وأحصيناها. فالله شاهدٌ على كلّ عملٍ عليمٌ به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله الشاهدِ على كلِّ عملٍ العليمِ به."},"action":{"text":"راقب اللهَ في عملك، فهو لم يغب عنك لحظةً، ويقصّ عليك عملك بعلم."}},{"n":8,"reflection":{"text":"«والوزن يومئذ الحق فمن ثقلت موازينه فأولئك هم المفلحون» — ووزنُ الأعمال يومَ القيامة بالعدل الحقّ الذي لا جورَ فيه؛ فمن رجحت حسناتُه فأولئك هم الفائزون بالجنّة والنجاة. فالفلاحُ لمن ثقلت موازينُ حسناته. فاعمل ما يُثقل ميزانك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لما يُثقل ميزانَ الحسناتِ يومَ الوزن."},"action":{"text":"أكثِر من الحسنات الثقيلة في الميزان (كالتوحيد والذكر)، فالفلاحُ لمن ثقُل ميزانه."}},{"n":9,"reflection":{"text":"«ومن خفت موازينه فأولئك الذين خسروا أنفسهم بما كانوا بآياتنا يظلمون» — ومن خفّت حسناتُه ورجحت سيّئاتُه فأولئك خسروا أنفسهم بسبب ظلمهم وجحودهم بآيات الله؛ فأعظمُ الخسارة خسارةُ النفس في النار. فالخسرانُ الأكبرُ لمن خفّ ميزانُه بالتكذيب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من خفّةِ الميزانِ بالتكذيبِ والمعاصي."},"action":{"text":"احذر ما يُخفّف ميزانك من الذنوب والتكذيب، فخسارةُ النفس أعظمُ الخسران."}},{"n":10,"reflection":{"text":"«ولقد مكناكم في الأرض وجعلنا لكم فيها معايش قليلا ما تشكرون» — ولقد جعلنا لكم في الأرض قرارًا وتمكينًا، وهيّأنا لكم فيها أسبابَ المعيشة من مأكلٍ ومشربٍ ومكسب؛ ومع ذلك قليلٌ شكرُكم لهذه النعم. فالنعمُ تستوجب شكرًا كثيرًا لا قليلًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ التمكينِ والرزقِ في الأرض."},"action":{"text":"تأمّل نعمَ الله عليك في الأرض ورزقك فيها، وأكثِر من شكره عليها."}}]},{"title":"قصّةُ آدمَ وإبليس: الكبرُ أوّلُ معصية","range":[11,18],"theme":"سجودُ الملائكةِ وإباءُ إبليسَ كبرًا، وعداوتُه المعلَنةُ لبني آدم","verses":[{"n":11,"reflection":{"text":"«ولقد خلقناكم ثم صورناكم ثم قلنا للملائكة اسجدوا لآدم فسجدوا إلا إبليس لم يكن من الساجدين» — خلقنا أباكم آدمَ ثمّ صوّرناه في أحسن صورة، ثمّ أمرنا الملائكةَ بالسجود له تكريمًا فسجدوا إلا إبليس أبى واستكبر؛ فبدأ الشرُّ بالكبر. فأوّلُ ذنبٍ عُصي الله به الكبر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكبرِ أوّلِ معصيةٍ عُصي الله بها."},"action":{"text":"احذر الكبرَ، فهو أوّلُ ذنبٍ عصى به إبليسُ ربَّه فطُرد."}},{"n":12,"reflection":{"text":"«قال ما منعك ألا تسجد إذ أمرتك قال أنا خير منه خلقتني من نار وخلقته من طين» — سأل الله إبليسَ توبيخًا: ما منعك من السجود وقد أمرتك؟ فأجاب بالكبر والقياس الفاسد: أنا خيرٌ منه، خلقتني من نارٍ وخلقته من طين؛ فقدّم رأيه على أمر الله، وفضّل النارَ على الطين بجهل. فمعارضةُ أمر الله بالرأي والقياس بابُ الضلال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تقديمُ أمرِ الله على الرأيِ والقياسِ الفاسد."},"action":{"text":"سلّم لأمر الله ولا تعارضه برأيك أو قياسك، فمعارضتُه بالرأي هلاك."}},{"n":13,"reflection":{"text":"«قال فاهبط منها فما يكون لك أن تتكبر فيها فاخرج إنك من الصاغرين» — قال الله له: اهبط من الجنّة (أو المنزلة الرفيعة)، فليس لك أن تتكبّر فيها؛ فاخرج ذليلًا صاغرًا؛ فجزاءُ الكبر الذلُّ والطرد؛ فمن تكبّر أذلّه الله. فعاقبةُ الكبرِ الصَّغار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الكبرَ يورث الذلَّ والطرد."},"action":{"text":"تواضع لله وأمره، فالمتكبّرُ يُصغّره الله ويُذلّه كما أذلّ إبليس."}},{"n":14,"reflection":{"text":"«قال أنظرني إلى يوم يبعثون» — طلب إبليسُ أن يُمهله الله ولا يميته إلى يوم البعث ليتفرّغ لإغواء بني آدم؛ فسأل النَّظِرة لا التوبة، فازداد شرًّا. فالشقيُّ يطلب المهلةَ للشرّ لا للتوبة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ المهلةِ في الطاعةِ لا في المعصية."},"action":{"text":"اجعل مهلةَ عمرك في الطاعة والتوبة، لا في تسويفٍ أو معصية كما فعل إبليس."}},{"n":15,"reflection":{"text":"«قال إنك من المنظرين» — أجابه الله إلى الإمهال بحكمته: إنّك من المؤخَّرين إلى الوقت المعلوم؛ ليتمّ الابتلاءُ ويتبيّن الطائعُ من العاصي؛ فالإمهالُ ابتلاءٌ لا كرامة. فمهلةُ الله ابتلاءٌ لا رضًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ إمهالَ الله ابتلاءٌ وحكمةٌ لا رضا."},"action":{"text":"لا تظنّ الإمهالَ رضًا، فهو ابتلاءٌ ليتبيّن صدقُك في الطاعة."}},{"n":16,"reflection":{"text":"«قال فبما أغويتني لأقعدن لهم صراطك المستقيم» — أقسم إبليسُ لمّا حُكم بغوايته أن يترصّد لبني آدم على طريق الحقّ ليصدّهم عنه؛ فأعلن الحربَ على المؤمنين. فالشيطانُ يقعد لك على طريق الهدى ليصرفك عنه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من ترصّدِ الشيطانِ على طريق الهدى."},"action":{"text":"اثبت على الصراط المستقيم، واستعذ بالله من الشيطان القاعدِ لك عليه."}},{"n":17,"reflection":{"text":"«ثم لآتينهم من بين أيديهم ومن خلفهم وعن أيمانهم وعن شمائلهم ولا تجد أكثرهم شاكرين» — توعّد إبليسُ أن يأتي بني آدم من كلّ جهة (بتزهيدهم في الآخرة، وتخويفهم من الدنيا، وتلبيس الباطل، وتزيين الشهوات)، وأنّ أكثرهم لن يكونوا شاكرين؛ فحصر الأكثرَ في الغفلة. فالشيطانُ يحاصرك من كلّ جهة، فكن من الشاكرين القليل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على الشكرِ الذي يعصم من كيد الشيطان."},"action":{"text":"كن من الشاكرين القليل، فالشكرُ حصنٌ من الشيطان الذي يأتيك من كلّ جهة."}},{"n":18,"reflection":{"text":"«قال اخرج منها مذءوما مدحورا لمن تبعك منهم لأملأن جهنم منكم أجمعين» — قال الله لإبليس: اخرج ذميمًا مطرودًا مبعَدًا؛ ثمّ أقسم: من تبعك من بني آدم لأملأنّ جهنم منكم جميعًا — منك ومنهم؛ فمصيرُ الشيطانِ وأتباعِه النار. فاحذر أن تكون من أتباع من مصيرُه جهنم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من اتّباعِ الشيطانِ الذي مصيرُه ومصيرُ أتباعِه النار."},"action":{"text":"لا تتّبع الشيطانَ في شيء، فقد أقسم الله أن يملأ جهنّم منه ومن أتباعه."}}]},{"title":"إخراجُ آدمَ من الجنّة، وأوّلُ توبة","range":[19,25],"theme":"وسوسةُ الشيطانِ ونصحُه الكاذب، وزلّةُ آدمَ وتوبتُه، والهبوطُ إلى الأرض","verses":[{"n":19,"reflection":{"text":"«ويا آدم اسكن أنت وزوجك الجنة فكلا من حيث شئتما ولا تقربا هذه الشجرة فتكونا من الظالمين» — وقال الله لآدم: اسكن أنت وزوجُك حوّاءُ الجنّة، وكلا من ثمارها من أيّ مكانٍ شئتما، ولكن لا تقربا هذه الشجرةَ المعيّنة فتكونا من الظالمين لأنفسكما؛ فأباح الكثيرَ وحرّم واحدةً ابتلاءً. فالنهيُ عن القليلِ مع إباحةِ الكثيرِ ابتلاءٌ يسير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحدود الله والوقوفُ عند نهيه."},"action":{"text":"قِف عند حدود الله ولو حرّم عليك يسيرًا مع إباحته الكثير، فذاك ابتلاءُ الطاعة."}},{"n":20,"reflection":{"text":"«فوسوس لهما الشيطان ليبدي لهما ما ووري عنهما من سوآتهما وقال ما نهاكما ربكما عن هذه الشجرة إلا أن تكونا ملكين أو تكونا من الخالدين» — فوسوس الشيطانُ لآدمَ وحوّاءَ ليكشف لهما عوراتهما التي كانت مستورة، وزيّن لهما الأكلَ زاعمًا أنّ الله ما نهاهما إلا خشيةَ أن يصيرا ملَكين أو خالدَين؛ فأوهمهما أنّ في المعصية خيرًا. فالشيطانُ يزيّن المعصيةَ بأنّها منفعة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"كشفُ خداعِ الشيطانِ الذي يزيّن المعصيةَ منفعةً."},"action":{"text":"احذر تزيينَ الشيطان للمعصية بدعوى المصلحة، فوعدُه غرور."}},{"n":21,"reflection":{"text":"«وقاسمهما إني لكما لمن الناصحين» — وحلف لهما الشيطانُ كاذبًا أنّه ناصحٌ لهما مشفقٌ عليهما؛ فاغترّا بيمينه إذ لم يظنّا أنّ أحدًا يحلف بالله كاذبًا؛ فالمؤمنُ يُخدَع بيمينٍ كاذبة. فاحذر من يحلف لك بالله على باطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ ممن يتوسّلُ باليمينِ الكاذبةِ لخداعك."},"action":{"text":"لا تغترّ بمن يحلف لك على باطل، فقد خدع الشيطانُ أبانا آدمَ بيمين."}},{"n":22,"reflection":{"text":"«فدلاهما بغرور فلما ذاقا الشجرة بدت لهما سوآتهما وطفقا يخصفان عليهما من ورق الجنة وناداهما ربهما ألم أنهكما عن تلكما الشجرة وأقل لكما إن الشيطان لكما عدو مبين» — فأنزلهما الشيطانُ عن منزلتهما بالخداع، فلمّا أكلا من الشجرة انكشفت عوراتهما فأخذا يلصقان عليهما من ورق الجنّة سترًا؛ وعاتبهما ربّهما: ألم أنهكما عن هذه الشجرة وأُخبركما أنّ الشيطانَ عدوٌّ مبين؟ فعاقبةُ طاعةِ الشيطانِ العُريُ والفضيحة. فمعصيةُ الله تكشف السترَ وتورث الخزي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ المعصيةَ تكشف السترَ وتورث الندم."},"action":{"text":"اجتنب المعصيةَ فإنّها تكشف سترَ العبد وتورثه الخزي والندم."}},{"n":23,"reflection":{"text":"«قالا ربنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكونن من الخاسرين» — أقرّ آدمُ وحوّاءُ بذنبهما بذلٍّ وانكسار: ربّنا ظلمنا أنفسنا، وإن لم تغفر لنا وترحمنا لنكوننّ من الخاسرين؛ فهذا دعاءُ التوبة النصوح: اعترافٌ بالذنب وافتقارٌ إلى المغفرة؛ فبه غفر الله لهما، بخلاف إبليسَ الذي أصرّ. فالتوبةُ اعترافٌ وانكسارٌ يجبّ الخطيئة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التوبةُ بالاعترافِ بالذنبِ والافتقارِ إلى الله."},"action":{"text":"إذا أذنبت فاعترف وتُب منكسرًا كآدم، ولا تُصرّ متكبّرًا كإبليس."}},{"n":24,"reflection":{"text":"«قال اهبطوا بعضكم لبعض عدو ولكم في الأرض مستقر ومتاع إلى حين» — قال الله لآدمَ وحوّاءَ وإبليس: اهبطوا إلى الأرض، بعضُكم لبعضٍ عدوّ (ابنُ آدم والشيطان)؛ ولكم في الأرض قرارٌ وعيشٌ ومتاعٌ إلى أجلٍ مقدّر؛ فبدأت رحلةُ الابتلاء في الأرض. فالحياةُ الدنيا دارُ ابتلاءٍ ومتاعٍ مؤقّت.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ أنّ الدنيا دارُ عداوةٍ للشيطانِ ومتاعٍ مؤقّت."},"action":{"text":"عِش في الأرض على حذرٍ من عدوّك الشيطان، واعلم أنّ متاعها إلى حين."}},{"n":25,"reflection":{"text":"«قال فيها تحيون وفيها تموتون ومنها تخرجون» — قال الله: في الأرض تعيشون حياتكم، وفيها تموتون وتُدفنون، ومنها تُخرجون أحياءً يومَ البعث؛ فأطوارُكم كلُّها فيها بتقدير الله؛ فمنها خُلقتم وإليها تعودون ومنها تُبعثون. فتذكّر أنّ منتهاك بعثٌ وحساب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للبعثِ من الأرضِ التي فيها الحياةُ والموت."},"action":{"text":"اعمل في حياتك على الأرض لبعثٍ منها وحساب، فمصيرُك الخروجُ للجزاء."}}]},{"title":"لباسُ التقوى، والتحذيرُ من فتنةِ الشيطان","range":[26,30],"theme":"نعمةُ اللباسِ الحسّيِّ والمعنويّ، وعداوةُ الشيطانِ الخفيّة، وأنّ الله لا يأمر بالفحشاء","verses":[{"n":26,"reflection":{"text":"«يا بني آدم قد أنزلنا عليكم لباسا يواري سوآتكم وريشا ولباس التقوى ذلك خير ذلك من آيات الله لعلهم يذكرون» — يا بني آدم قد يسّرنا لكم لباسًا يستر عوراتكم وزينةً تتجمّلون بها؛ ولباسُ التقوى — الإيمانُ والعملُ الصالحُ الذي يستر عيوبَ القلب — خيرٌ من لباس البدن؛ ذلك من نعم الله وآياته لتذكّروا وتشكروا. فأعظمُ اللباسِ لباسُ التقوى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتناءُ بلباسِ التقوى قبل لباسِ البدن."},"action":{"text":"اهتمّ بلباس التقوى (الإيمانِ والعمل) كما تهتمّ بستر بدنك، فهو خيرٌ وأبقى."}},{"n":27,"reflection":{"text":"«يا بني آدم لا يفتننكم الشيطان كما أخرج أبويكم من الجنة ينزع عنهما لباسهما ليريهما سوآتهما إنه يراكم هو وقبيله من حيث لا ترونهم إنا جعلنا الشياطين أولياء للذين لا يؤمنون» — يا بني آدم احذروا أن يخدعكم الشيطانُ فيوقعكم في المعصية كما أخرج أبويكم من الجنّة وكشف عورتهما؛ فهو وجنودُه يرونكم من حيث لا ترونهم فاحذروهم؛ وقد جعلنا الشياطينَ أولياءَ لمن لا يؤمن. فالعدوُّ يراك ولا تراه، فاستعذ بمن يراه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عدوٍّ يراك ولا تراه بالاستعاذةِ بالله."},"action":{"text":"استعذ بالله من الشيطان دائمًا، فهو يراك من حيث لا تراه، وحصنُك ذكرُ الله."}},{"n":28,"reflection":{"text":"«وإذا فعلوا فاحشة قالوا وجدنا عليها آباءنا والله أمرنا بها قل إن الله لا يأمر بالفحشاء أتقولون على الله ما لا تعلمون» — إذا فعل المشركون قبيحًا (كالطواف عراةً) احتجّوا بتقليد الآباء ونسبوه إلى أمر الله؛ فردّ الله: إنّ الله لا يأمر بالفحشاء، فكيف تنسبونها إليه؟ أتقولون عليه ما لا علمَ لكم به؟ فنسبةُ القبيح إلى شرع الله افتراءٌ وجهل. فالله منزّهٌ أن يأمر بفاحشة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ شرعِ الله عن الفحشاء وتوقّي القولِ عليه بلا علم."},"action":{"text":"لا تنسب إلى دين الله ما يخالف الفطرة والحقّ، فالله لا يأمر بالفحشاء."}},{"n":29,"reflection":{"text":"«قل أمر ربي بالقسط وأقيموا وجوهكم عند كل مسجد وادعوه مخلصين له الدين كما بدأكم تعودون» — قل: إنّما أمر ربّي بالعدل والاستقامة، وأن توجّهوا عبادتكم لله في كلّ صلاةٍ ومسجد، وتدعوه مخلصين له الطاعةَ لا تشركوا به؛ وكما خلقكم أوّلَ مرّةٍ يعيدكم للبعث؛ فالإخلاصُ والعدلُ أمرُ الله، والبعثُ حقّ. فأخلِص عبادتك لله كما أُمرت.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإخلاصُ في العبادةِ والاستقامةُ على العدل."},"action":{"text":"أخلِص عبادتك لله في كلّ صلاة، والزم العدلَ في أمرك، مستحضرًا عودتك إليه."}},{"n":30,"reflection":{"text":"«فريقا هدى وفريقا حق عليهم الضلالة إنهم اتخذوا الشياطين أولياء من دون الله ويحسبون أنهم مهتدون» — انقسم الناسُ فريقين: فريقٌ هداه الله بفضله، وفريقٌ استحقّ الضلالةَ بعدله لأنّهم اتّخذوا الشياطينَ أولياءَ يطيعونهم، وهم مع ذلك يظنّون أنّهم على هدى؛ فأخطرُ الضلالِ ضلالٌ يُحسب صاحبُه أنّه هدى. فاحذر أن تكون ضالًّا تحسب نفسك مهتديًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الضلالِ الذي يظنّه صاحبُه هدًى."},"action":{"text":"حاسِب نفسك بميزان الوحي، فأخطرُ الضلال ما يظنّه صاحبُه هدايةً."}}]},{"title":"خذوا زينتكم، وما حرّمه الله حقًّا","range":[31,39],"theme":"إباحةُ الزينةِ والطيّباتِ بلا إسراف، وحصرُ المحرّماتِ الحقيقيّة، وعاقبةُ المكذّبين","verses":[{"n":31,"reflection":{"text":"«يا بني آدم خذوا زينتكم عند كل مسجد وكلوا واشربوا ولا تسرفوا إنه لا يحب المسرفين» — يا بني آدم تجمّلوا بستر العورة والثياب الحسنة عند الصلاة والطواف، وكلوا واشربوا من الطيّبات ولا تتجاوزوا الحدَّ إسرافًا أو تحريمًا لما أحلّ؛ إنّ الله لا يحبّ المسرفين. (فيها أصلُ التجمّل للصلاة، والاعتدالِ في الأكل). فالدينُ زينةٌ واعتدالٌ لا حرمانَ ولا إسراف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التجمّلُ للصلاةِ والاعتدالُ في الأكلِ والشرب."},"action":{"text":"تجمّل لصلاتك واستر عورتك، وكل واشرب باعتدالٍ بلا إسراف، فالله لا يحبّ المسرفين."}},{"n":32,"reflection":{"text":"«قل من حرم زينة الله التي أخرج لعباده والطيبات من الرزق قل هي للذين آمنوا في الحياة الدنيا خالصة يوم القيامة كذلك نفصل الآيات لقوم يعلمون» — قل منكرًا على من حرّم الزينةَ والطيّبات: من حرّم زينةَ الله التي أخرجها لعباده والطيّباتِ من الرزق؟ هي في الدنيا للمؤمنين ولغيرهم، لكنّها خالصةٌ للمؤمنين يومَ القيامة؛ كذلك نبيّن الآياتِ لمن يعلم. فالطيّباتُ نعمةٌ للانتفاع بها مع الشكر لا للتحريم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التمتّعُ بطيّباتِ الرزقِ مع الشكرِ لا التحريم."},"action":{"text":"تمتّع بما أحلّ الله من الزينة والطيّبات شاكرًا، ولا تحرّم ما لم يحرّمه الله."}},{"n":33,"reflection":{"text":"«قل إنما حرم ربي الفواحش ما ظهر منها وما بطن والإثم والبغي بغير الحق وأن تشركوا بالله ما لم ينزل به سلطانا وأن تقولوا على الله ما لا تعلمون» — قل: إنّما حرّم ربّي الفواحشَ ظاهرَها وباطنها، وكلَّ إثم، والظلمَ والعدوانَ بغير حقّ، والشركَ بالله الذي لا حجّةَ عليه، والقولَ على الله بلا علم؛ فهذه هي المحرّمات الحقيقيّة لا ما ابتدعوه. فأعظمُ المحرّماتِ الشركُ والقولُ على الله بلا علم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ المحرّماتِ الحقيقيّةِ واجتنابُها."},"action":{"text":"اجتنب ما حرّم الله حقًّا: الفواحشَ والظلمَ والشركَ والقولَ عليه بلا علم."}},{"n":34,"reflection":{"text":"«ولكل أمة أجل فإذا جاء أجلهم لا يستأخرون ساعة ولا يستقدمون» — لكلّ أمّةٍ أجلٌ مقدّرٌ لبقائها أو لعذابها؛ فإذا جاء وقتُهم لم يتأخّروا عنه لحظةً ولم يتقدّموا؛ فآجالُ الأمم والأفرادِ بيد الله لا تتغيّر. فلا يُستعجل العذابُ ولا يُستبطأ، فكلُّ شيءٍ بأجله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الآجالَ بيد الله في وقتها المقدّر."},"action":{"text":"لا تستعجل قضاءَ الله، واعمل قبل أجلك، فلكلّ أمّةٍ ونفسٍ أجلٌ لا يتقدّم ولا يتأخّر."}},{"n":35,"reflection":{"text":"«يا بني آدم إما يأتينكم رسل منكم يقصون عليكم آياتي فمن اتقى وأصلح فلا خوف عليهم ولا هم يحزنون» — يا بني آدم إن جاءكم رسلٌ منكم يتلون عليكم آياتي، فمن اتّقى الله وأصلح عملَه باتّباعهم فلا خوفٌ عليهم فيما يستقبلون ولا حزنٌ على ما مضى؛ فالنجاةُ باتّباع الرسل والتقوى والإصلاح. فأمنُ الآخرةِ لمن اتّقى وأصلح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التقوى والإصلاحُ باتّباعِ الرسلِ سبيلُ الأمن."},"action":{"text":"اتّبع ما جاءت به الرسل واتّقِ وأصلح عملك، فبذلك يأمن قلبُك."}},{"n":36,"reflection":{"text":"«والذين كذبوا بآياتنا واستكبروا عنها أولئك أصحاب النار هم فيها خالدون» — والذين كذّبوا بآيات الله وتكبّروا عن قبولها والعمل بها، أولئك أصحابُ النار خالدون فيها؛ فجمعوا بين التكذيب والاستكبار. فالتكذيبُ مع الكبرِ عاقبتُه الخلودُ في النار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي التكذيبِ والاستكبارِ عن آيات الله."},"action":{"text":"اقبل الحقَّ متواضعًا، فالتكذيبُ والكبرُ عن آيات الله موجبٌ للنار."}},{"n":37,"reflection":{"text":"«فمن أظلم ممن افترى على الله كذبا أو كذب بآياته أولئك ينالهم نصيبهم من الكتاب حتى إذا جاءتهم رسلنا يتوفونهم قالوا أين ما كنتم تدعون من دون الله قالوا ضلوا عنا وشهدوا على أنفسهم أنهم كانوا كافرين» — لا أظلمَ ممّن كذب على الله أو كذّب بآياته؛ ينالهم ما كُتب لهم من رزقٍ وعمرٍ، حتى إذا جاءتهم ملائكةُ الموت تقبض أرواحهم سُئلوا: أين آلهتكم التي تعبدون؟ فيقولون: غابوا عنّا ولم ينفعونا، ويشهدون على أنفسهم بالكفر. فالمعبوداتُ الباطلةُ تتخلّى عن عابديها عند الموت.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ التعلّقِ بمعبودٍ يتخلّى عنك عند الموت."},"action":{"text":"لا تعلّق قلبك بغير الله، فكلُّ ما سواه يتخلّى عنك عند الموت والحساب."}},{"n":38,"reflection":{"text":"«قال ادخلوا في أمم قد خلت من قبلكم من الجن والإنس في النار كلما دخلت أمة لعنت أختها... قالت أخراهم لأولاهم ربنا هؤلاء أضلونا فآتهم عذابا ضعفا من النار قال لكل ضعف ولكن لا تعلمون» — يقال للكافرين: ادخلوا النارَ مع أممٍ سبقتكم من الجنّ والإنس؛ كلّما دخلت أمّةٌ لعنت التي أضلّتها؛ فيقول الأتباعُ عن قادتهم: ربّنا هؤلاء أضلّونا فضاعِف عذابهم؛ فيقول الله: لكلٍّ عذابٌ مضاعف (للقادةِ بضلالهم وإضلالهم، وللأتباعِ بكفرهم وتقليدهم) ولكن لا تعلمون قدره. فالتقليدُ في الضلال لا يُنجي، وكلٌّ يحمل وزره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ التقليدِ في الضلالِ وتحمّلُ مسؤوليّةِ الاتّباع."},"action":{"text":"لا تقلّد أحدًا في باطل، فالتابعُ والمتبوعُ في الضلال كلاهما معذّب."}},{"n":39,"reflection":{"text":"«وقالت أولاهم لأخراهم فما كان لكم علينا من فضل فذوقوا العذاب بما كنتم تكسبون» — ويقول القادةُ لأتباعهم: لم يكن لكم علينا فضلٌ حتى تُلقوا اللومَ علينا، بل اخترتم الكفرَ باختياركم كما اخترناه؛ فذوقوا العذابَ بما كسبتم من الكفر والتقليد. فكلٌّ مسؤولٌ عن كفره، ولا عذرَ بالتقليد. فلا تُلقِ ذنبك على غيرك، فكلٌّ يُجزى بكسبه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحمّلُ مسؤوليّةِ الاختيارِ وعدمُ إلقاءِ اللومِ على الغير."},"action":{"text":"تحمّل مسؤوليّة اختيارك، ولا تعلّق ذنبك على من قلّدته، فكلٌّ يُجزى بكسبه."}}]},{"title":"جزاءُ المكذّبين، وجزاءُ المؤمنين","range":[40,43],"theme":"حرمانُ المستكبرين من الجنّة، ونعيمُ المؤمنين ونزعُ الغلّ من صدورهم","verses":[{"n":40,"reflection":{"text":"«إن الذين كذبوا بآياتنا واستكبروا عنها لا تفتح لهم أبواب السماء ولا يدخلون الجنة حتى يلج الجمل في سم الخياط وكذلك نجزي المجرمين» — الذين كذّبوا بآيات الله وتكبّروا عنها لا تُفتح لأرواحهم أبوابُ السماء عند موتها، ولا يدخلون الجنّة أبدًا — وهو مستحيلٌ كولوج الجمل الضخم في ثقب الإبرة —؛ وكذلك نجزي المجرمين. فالكبرُ عن الحقّ يغلق أبوابَ السماء والجنّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الكبرِ عن الحقّ الذي يغلق أبوابَ الرحمة."},"action":{"text":"تواضع للحقّ، فالمستكبرون عنه تُغلق دونهم أبوابُ السماء والجنّة."}},{"n":41,"reflection":{"text":"«لهم من جهنم مهاد ومن فوقهم غواش وكذلك نجزي الظالمين» — لهؤلاء الظالمين من جهنّم فراشٌ يفترشونه، ومن فوقهم أغطيةٌ من النار تغشاهم؛ فأحاط بهم العذابُ من تحتهم وفوقهم؛ وكذلك نجزي الظالمين. فعذابُ الظالمين محيطٌ بهم من كلّ جهة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الظلمِ الذي يحيط بصاحبه العذاب."},"action":{"text":"اجتنب الظلمَ، فجزاءُ الظالمين نارٌ من تحتهم ومن فوقهم تحيط بهم."}},{"n":42,"reflection":{"text":"«والذين آمنوا وعملوا الصالحات لا نكلف نفسا إلا وسعها أولئك أصحاب الجنة هم فيها خالدون» — والذين آمنوا وعملوا الصالحاتِ — والله لا يكلّف نفسًا فوق طاقتها، فالتكاليفُ في وسع العبد — أولئك أصحابُ الجنّة خالدون فيها؛ ففي ذكر «لا نكلّف» بشارةٌ أنّ الجنّةَ في متناول العمل الميسور. فالجنّةُ لمن آمن وعمل بما يطيق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للجنّةِ بما تطيق، فالتكليفُ في الوسع."},"action":{"text":"اعمل للجنّة بما تقدر عليه، فالله لا يكلّفك فوق وسعك، والجنّةُ ثمرةُ الإيمان والعمل."}},{"n":43,"reflection":{"text":"«ونزعنا ما في صدورهم من غل تجري من تحتهم الأنهار وقالوا الحمد لله الذي هدانا لهذا وما كنا لنهتدي لولا أن هدانا الله لقد جاءت رسل ربنا بالحق ونودوا أن تلكم الجنة أورثتموها بما كنتم تعملون» — ينزع الله من صدور أهل الجنّة كلَّ حقدٍ وحسدٍ فيدخلونها بقلوبٍ سليمةٍ متحابّة، تجري تحتهم الأنهار؛ فيحمدون الله الذي هداهم ويقرّون أنّهم ما كانوا ليهتدوا لولا هدايته، وأنّ رسلَ ربّهم جاؤوا بالحقّ؛ ويُنادَون أنّ هذه الجنّةَ أورثكموها الله بعملكم فضلًا منه. فالهدايةُ محضُ فضلِ الله، والجنّةُ برحمته بعد العمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"نسبةُ الهدايةِ لفضلِ الله وسلامةُ الصدرِ من الغلّ."},"action":{"text":"احمد الله على هدايتك، ونقِّ قلبك من الغلّ والحسد، فأهلُ الجنّة سليمةٌ صدورهم."}}]},{"title":"نداءُ أهل الجنّةِ والنار، وأصحابُ الأعراف","range":[44,49],"theme":"تحاورُ أهلِ الدارين، ولعنةُ الظالمين، ورجالُ الأعرافِ بين الجنّةِ والنار","verses":[{"n":44,"reflection":{"text":"«ونادى أصحاب الجنة أصحاب النار أن قد وجدنا ما وعدنا ربنا حقا فهل وجدتم ما وعد ربكم حقا قالوا نعم فأذن مؤذن بينهم أن لعنة الله على الظالمين» — ينادي أهلُ الجنّة أهلَ النار: قد وجدنا ما وعدنا الله من النعيم حقًّا، فهل وجدتم ما وعدكم من العذاب حقًّا؟ فيقرّون: نعم؛ فيؤذّن مؤذّنٌ بينهم بأنّ لعنةَ الله على الظالمين؛ فيُفضح الظالمون على رؤوس الأشهاد. فوعدُ الله حقٌّ لأهل الدارين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ وعدَ الله ووعيدَه حقٌّ لا يتخلّف."},"action":{"text":"صدّق بوعد الله ووعيده، فأهلُ الدارين يشهدون يومَ القيامة أنّه حقّ."}},{"n":45,"reflection":{"text":"«الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالآخرة كافرون» — الظالمون الملعونون هم الذين يمنعون الناسَ عن دين الله، ويطلبون لسبيله الاعوجاجَ بالتشكيك والتحريف، وهم بالآخرة جاحدون؛ فجمعوا بين الصدّ عن الحقّ وإنكار البعث. فالصدُّ عن سبيل الله وتشويهُه من صفات أهل اللعنة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الصدِّ عن سبيل الله وتشويهِه."},"action":{"text":"لا تصدّ أحدًا عن الحقّ ولا تُشوّهه، بل كن داعيًا إليه ميسّرًا له."}},{"n":46,"reflection":{"text":"«وبينهما حجاب وعلى الأعراف رجال يعرفون كلا بسيماهم ونادوا أصحاب الجنة أن سلام عليكم لم يدخلوها وهم يطمعون» — وبين الجنّة والنار حاجزٌ (السور الذي له بابٌ)، وعلى أعلاه (الأعراف) رجالٌ استوت حسناتُهم وسيّئاتهم، يعرفون أهلَ الجنّة وأهلَ النار بعلاماتهم؛ يُنادون أهلَ الجنّة بالسلام، ولمّا يدخلوها بعدُ وهم يطمعون في رحمة الله أن يدخلهم إيّاها؛ فهم بين خوفٍ ورجاء ثمّ يُدخلهم الله الجنّة برحمته. فالرجاءُ في رحمة الله يبقى حتى في أحرج المواقف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"بقاءُ الرجاءِ في رحمةِ الله في كلِّ موقف."},"action":{"text":"لا تقنط من رحمة الله، فأصحابُ الأعراف بين الجنّة والنار يطمعون في رحمته فيدخلهم الجنّة."}},{"n":47,"reflection":{"text":"«وإذا صرفت أبصارهم تلقاء أصحاب النار قالوا ربنا لا تجعلنا مع القوم الظالمين» — وإذا وُجّهت أبصارُ أصحاب الأعراف نحو أهل النار وأبصروا هولها فزعوا ودعوا: ربّنا لا تجعلنا مع القوم الظالمين؛ فاستعاذوا من مصير الظالمين. فرؤيةُ عاقبةِ الظالمين تبعث على الالتجاء إلى الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الالتجاءُ إلى الله خوفًا من مصيرِ الظالمين."},"action":{"text":"استعذ بالله أن تكون مع الظالمين، وادعُه أن يقيك مصيرهم."}},{"n":48,"reflection":{"text":"«ونادى أصحاب الأعراف رجالا يعرفونهم بسيماهم قالوا ما أغنى عنكم جمعكم وما كنتم تستكبرون» — ونادى أصحابُ الأعراف رجالًا من كبراء أهل النار يعرفونهم بعلاماتهم: ما نفعكم كثرةُ أموالكم وأتباعكم، ولا كبرُكم في الدنيا؟ فها أنتم في النار؛ فبطل ما اتّكلتم عليه. فالجمعُ والكبرُ لا يُغنيان يومَ القيامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ المالَ والجاهَ والكبرَ لا يُغني يومَ القيامة."},"action":{"text":"لا تتّكل على مالٍ أو جاهٍ أو كثرة، فلن يُغني عنك يومَ القيامة شيئًا إلا عملُك."}},{"n":49,"reflection":{"text":"«أهؤلاء الذين أقسمتم لا ينالهم الله برحمة ادخلوا الجنة لا خوف عليكم ولا أنتم تحزنون» — يقال توبيخًا لأهل النار مشيرًا إلى ضعفاء المؤمنين: أهؤلاء الذين حلفتم في الدنيا أنّ الله لن يرحمهم لفقرهم وضعفهم؟ ثمّ يقال لهؤلاء المؤمنين: ادخلوا الجنّة لا خوفٌ عليكم ولا حزن؛ فتنقلب موازينُ الدنيا. فلا تحتقر مؤمنًا، فقد يكون عند الله أرفعَ منك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ احتقارِ المؤمنِ الضعيفِ فقد يكون أرفعَ عند الله."},"action":{"text":"لا تحتقر أحدًا من المؤمنين، فربّ ضعيفٍ محتقَرٍ يدخل الجنّةَ ويُوبَّخ من ازدراه."}}]},{"title":"نداءُ أهلِ النار، والكتابُ المفصّل","range":[50,53],"theme":"حرمانُ الكافرين من نعيم الجنّة، ونسيانُ الله لمن نسيه، وندمُهم يوم لا ينفع الندم","verses":[{"n":50,"reflection":{"text":"«ونادى أصحاب النار أصحاب الجنة أن أفيضوا علينا من الماء أو مما رزقكم الله قالوا إن الله حرمهما على الكافرين» — ينادي أهلُ النار أهلَ الجنّة مستغيثين: صبّوا علينا من الماء أو ممّا رزقكم الله؛ فيجيبون: إنّ الله حرّم الماءَ والطعامَ على الكافرين جزاءً لكفرهم؛ فلا يجدون غوثًا. فمن حُرم رحمةَ الله في الدنيا بالكفر حُرمها في الآخرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ رحمةِ الله في الدنيا قبل فواتها."},"action":{"text":"اطلب فضلَ الله ورحمته بالإيمان اليوم، فمن حُرمها بالكفر لا يجدها يومَ القيامة."}},{"n":51,"reflection":{"text":"«الذين اتخذوا دينهم لهوا ولعبا وغرتهم الحياة الدنيا فاليوم ننساهم كما نسوا لقاء يومهم هذا وما كانوا بآياتنا يجحدون» — هؤلاء الكافرون جعلوا دينهم لهوًا ولعبًا وخدعتهم الدنيا؛ فاليوم نتركهم في العذاب كأنّهم منسيّون، جزاءً بأنّهم نسوا الاستعدادَ لهذا اليوم وجحدوا آياتِ الله؛ فالجزاءُ من جنس العمل. فمن نسي الآخرةَ في الدنيا نُسي في العذاب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من نسيانِ الآخرةِ واتّخاذِ الدينِ لهوًا."},"action":{"text":"لا تجعل دينك لهوًا ولا تنسَ لقاء الله، فمن نسي الآخرة تركه الله في عذابه."}},{"n":52,"reflection":{"text":"«ولقد جئناهم بكتاب فصلناه على علم هدى ورحمة لقوم يؤمنون» — ولقد جئنا الناسَ بالقرآن، بيّنّاه وفصّلنا أحكامَه عن علمٍ منّا بمصالحهم، هدًى من الضلال ورحمةً لمن آمن به وعمل؛ فالحجّةُ قامت بإنزاله. فالقرآنُ هدًى ورحمةٌ لمن آمن به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تلقّي القرآنِ هدًى ورحمةً والعملُ به."},"action":{"text":"اجعل القرآنَ هاديك ورحمتك، فقد فصّله الله بعلمٍ لمن آمن به وعمل."}},{"n":53,"reflection":{"text":"«هل ينظرون إلا تأويله يوم يأتي تأويله يقول الذين نسوه من قبل قد جاءت رسل ربنا بالحق فهل لنا من شفعاء فيشفعوا لنا أو نرد فنعمل غير الذي كنا نعمل قد خسروا أنفسهم وضل عنهم ما كانوا يفترون» — ما ينتظر المكذّبون إلا وقوعَ ما أخبر به القرآن من الجزاء؛ فيومَ يقع يقول الذين أعرضوا عنه: قد جاءت رسلُ ربّنا بالحقّ، فهل من شفيعٍ يشفع لنا أو نُردّ للدنيا لنعمل صالحًا؟ لكن فات الأوان؛ قد خسروا أنفسهم وغاب عنهم ما كانوا يعبدون؛ فالتمنّي بعد الموت لا ينفع. فبادر بالعمل قبل يومٍ يُتمنّى فيه الرجوعُ ولا رجوع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالعملِ قبل يومٍ يُتمنّى فيه الرجوعُ ولا يُجاب."},"action":{"text":"اعمل صالحًا الآن، فأهلُ النار يتمنّون الرجوعَ للعمل فلا يُجابون."}}]},{"title":"استوى على العرش، وأدبُ الدعاء","range":[54,58],"theme":"عظمةُ الخالقِ المستوي على عرشه، والأمرُ بالدعاءِ خوفًا وطمعًا، وآيةُ إحياءِ الأرض","verses":[{"n":54,"reflection":{"text":"«إن ربكم الله الذي خلق السماوات والأرض في ستة أيام ثم استوى على العرش يغشي الليل النهار يطلبه حثيثا والشمس والقمر والنجوم مسخرات بأمره ألا له الخلق والأمر تبارك الله رب العالمين» — إنّ ربّكم الله الذي خلق السماوات والأرض في ستّة أيام ثمّ استوى على العرش استواءً يليق بجلاله؛ يُغطّي الليلَ بالنهار يتبع كلٌّ منهما الآخرَ سريعًا، وسخّر الشمسَ والقمرَ والنجومَ بأمره؛ ألا له وحده الخلقُ والتدبير؛ تعاظم وكثُر خيرُه ربُّ العالمين. فمن له الخلقُ والأمرُ هو المعبودُ وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["رب العالمين"],"heart_state":{"text":"تعظيمُ الخالقِ الذي له الخلقُ والأمرُ وحده."},"action":{"text":"عظّم اللهَ الذي خلق الكونَ ودبّره، وأفرِده بالعبادة، فله الخلقُ والأمر."}},{"n":55,"reflection":{"text":"«ادعوا ربكم تضرعا وخفية إنه لا يحب المعتدين» — ادعوا ربّكم متذلّلين مسرّين، فالإسرارُ أقربُ للإخلاص وأبعدُ عن الرياء؛ إنّه لا يحبّ المعتدين في الدعاء (بالجهر الزائد، أو سؤال ما لا يليق، أو التكلّف)؛ فأدبُ الدعاء التذلّلُ والإخفاء. فادعُ الله بخضوعٍ وإخلاص.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعاءُ بتذلّلٍ وإخفاءٍ وإخلاص."},"action":{"text":"ادعُ الله متضرّعًا في خفيةٍ بقلبٍ خاشع، ولا تعتدِ في دعائك بتكلّفٍ أو رياء."}},{"n":56,"reflection":{"text":"«ولا تفسدوا في الأرض بعد إصلاحها وادعوه خوفا وطمعا إن رحمة الله قريب من المحسنين» — ولا تُفسدوا في الأرض بالمعاصي والشرك بعد أن أصلحها الله بالشرائع وبعثةِ الرسل؛ وادعوه خائفين من عقابه طامعين في رحمته؛ إنّ رحمةَ الله قريبةٌ من المحسنين في عبادتهم ومعاملتهم؛ فالإحسانُ يقرّب الرحمة. فالجمعُ بين الخوفِ والطمعِ في الدعاء، والإحسانُ سببُ الرحمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الرحمن"],"heart_state":{"text":"الدعاءُ بين الخوفِ والطمع، والإحسانُ لتقربَ الرحمة."},"action":{"text":"ادعُ الله خائفًا طامعًا، وأحسِن في عملك، فرحمتُه قريبةٌ من المحسنين، ولا تُفسد في الأرض."}},{"n":57,"reflection":{"text":"«وهو الذي يرسل الرياح بشرا بين يدي رحمته حتى إذا أقلت سحابا ثقالا سقناه لبلد ميت فأنزلنا به الماء فأخرجنا به من كل الثمرات كذلك نخرج الموتى لعلكم تذكرون» — هو الذي يرسل الرياحَ مبشّراتٍ بالمطر بين يدي رحمته، حتى إذا حملت سحابًا مثقلًا بالماء سُقناه إلى أرضٍ ميّتةٍ فأنزلنا المطرَ فأنبتنا كلَّ الثمرات؛ وكما نُحيي الأرضَ الميّتة بالمطر نُخرج الموتى من قبورهم للبعث؛ لعلّكم تتذكّرون فتعتبروا. فإحياءُ الأرضِ دليلٌ محسوسٌ على البعث.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستدلالُ بإحياءِ الأرضِ على البعثِ والقدرة."},"action":{"text":"تأمّل إحياءَ الأرض الميّتة بالمطر، فمن أحياها يُحيي الموتى، فأيقن بالبعث."}},{"n":58,"reflection":{"text":"«والبلد الطيب يخرج نباته بإذن ربه والذي خبث لا يخرج إلا نكدا كذلك نصرف الآيات لقوم يشكرون» — والأرضُ الطيّبةُ الكريمةُ يخرج نباتها وافرًا حسنًا بإذن ربّها، والأرضُ السبخةُ الرديئةُ لا يخرج نباتُها إلا قليلًا عسيرًا؛ وهذا مثلٌ للقلوب: قلبُ المؤمن يقبل الهدى فيثمر، وقلبُ الكافر لا ينتفع؛ كذلك نبيّن الآياتِ لمن يشكر فينتفع. فالقلبُ الطيّبُ يثمر بالهدى، والخبيثُ لا ينتفع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تطييبُ القلبِ ليثمرَ بالهدى كالأرضِ الطيّبة."},"action":{"text":"اجعل قلبك أرضًا طيّبةً تقبل الهدى وتثمر عملًا، لا سبخةً لا تنتفع بالمطر."}}]},{"title":"قصّةُ نوحٍ: أوّلُ الرسلِ إلى مشركين","range":[59,64],"theme":"دعوةُ نوحٍ قومَه للتوحيد، وتكذيبُ الملأ، ونجاةُ المؤمنينَ وإغراقُ المكذّبين","verses":[{"n":59,"reflection":{"text":"«لقد أرسلنا نوحا إلى قومه فقال يا قوم اعبدوا الله ما لكم من إله غيره إني أخاف عليكم عذاب يوم عظيم» — أرسلنا نوحًا إلى قومه فدعاهم إلى أصل الدعوة كلِّها: اعبدوا الله وحده فما لكم معبودٌ سواه؛ وحذّرهم بشفقةٍ: إنّي أخاف عليكم عذابَ يومٍ عظيم إن أشركتم؛ فبدأ بالتوحيد كما بدأ به كلُّ رسول. فدعوةُ الرسلِ كلِّها واحدة: التوحيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"البَدءُ بالتوحيدِ في الدعوةِ والشفقةُ على الخلق."},"action":{"text":"اجعل التوحيدَ أوّلَ ما تدعو إليه، وانصح الناسَ بشفقةٍ خوفًا عليهم من العذاب."}},{"n":60,"reflection":{"text":"«قال الملأ من قومه إنا لنراك في ضلال مبين» — قال أشرافُ قومه وكبراؤهم: إنّا لنراك في ذهابٍ عن الصواب واضح؛ فقلبوا الحقيقةَ ورمَوا الناصحَ بالضلال؛ فهكذا يقابل المترفون دعوةَ الحقّ. فأهلُ الباطلِ يرمون الحقَّ بالضلال.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على اتّهامِ أهلِ الباطلِ لأهلِ الحقّ."},"action":{"text":"لا يزعزعك اتّهامُ المبطلين، فقد رُمي أنبياءُ الله بالضلال وهم أهدى الناس."}},{"n":61,"reflection":{"text":"«قال يا قوم ليس بي ضلالة ولكني رسول من رب العالمين» — أجابهم نوحٌ بلينٍ وثبات: يا قوم لست ضالًّا كما زعمتم، بل أنا رسولٌ من ربّ العالمين أبلّغكم عنه؛ فردّ التهمةَ بالحقّ بلا سبٍّ ولا انفعال. فالداعيةُ يردّ الباطلَ بالحلمِ والحجّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مقابلةُ الإساءةِ بالحلمِ وبيانِ الحقّ."},"action":{"text":"إذا اتُّهمت في دعوتك للحقّ فاردد بالحلم والبيان، لا بالمقابلة بالسبّ."}},{"n":62,"reflection":{"text":"«أبلغكم رسالات ربي وأنصح لكم وأعلم من الله ما لا تعلمون» — مهمّتي أن أبلّغكم ما أرسلني الله به، وأنصح لكم مريدًا خيركم، وأعلم من عظمة الله وعقابه ما لا تعلمون؛ فجمع بين البلاغ والنصح والعلم. فوظيفةُ الرسلِ: بلاغٌ ونصحٌ عن علم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين تبليغِ الحقِّ والنصحِ الصادقِ للخلق."},"action":{"text":"بلّغ الحقَّ وانصح للناس مريدًا خيرهم، فتلك سبيلُ الرسل في دعوتهم."}},{"n":63,"reflection":{"text":"«أوعجبتم أن جاءكم ذكر من ربكم على رجل منكم لينذركم ولتتقوا ولعلكم ترحمون» — أتعجبون أن يأتيكم تذكيرٌ من ربّكم على لسان رجلٍ منكم تعرفونه لينذركم؟ وفي بعثة البشر رحمةٌ لتفهموا عنه؛ والغايةُ أن تتّقوا فتُرحموا. فبعثةُ الرسولِ البشرِ نعمةٌ ورحمةٌ لا مدعاةَ للعجب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الرسولِ البشرِ الذي يُنذر رحمةً."},"action":{"text":"لا تستغرب أن يبعث الله رسولًا بشرًا منك، فذاك رحمةٌ لتتّقي فتُرحم."}},{"n":64,"reflection":{"text":"«فكذبوه فأنجيناه والذين معه في الفلك وأغرقنا الذين كذبوا بآياتنا إنهم كانوا قوما عمين» — فكذّب قومُ نوحٍ رسولَهم بعد طول الدعوة، فأنجينا نوحًا ومن آمن معه في السفينة، وأغرقنا المكذّبين بالطوفان؛ إنّهم كانوا عُمْيَ القلوب عن الحقّ؛ فكانت العاقبةُ للمؤمنين والهلاكُ للمكذّبين. فعاقبةُ التكذيبِ الهلاك، والنجاةُ للمؤمنين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ العاقبةَ للمؤمنينَ والهلاكَ للمكذّبين."},"action":{"text":"اثبت مع الحقّ ولو كُذّبت، فعاقبةُ المؤمنين النجاةُ والمكذّبين الهلاك."}}]},{"title":"قصّةُ هودٍ وعاد: التوحيدُ ونعمةُ التمكين","range":[65,72],"theme":"دعوةُ هودٍ عادًا للتوحيد، وتذكيرُهم بالنعم، وجدالُهم بأسماءِ آلهةٍ لا حقيقةَ لها","verses":[{"n":65,"reflection":{"text":"«وإلى عاد أخاهم هودا قال يا قوم اعبدوا الله ما لكم من إله غيره أفلا تتقون» — وأرسلنا إلى قبيلة عادٍ أخاهم في النسب هودًا، فدعاهم إلى ما دعا إليه كلُّ نبيّ: اعبدوا الله وحده فما لكم إلهٌ غيره؛ أفلا تتّقونه فتتركوا الشرك؟ فالدعوةُ واحدةٌ، والرسولُ من قومهم أرفقُ بهم. فأصلُ رسالةِ كلِّ نبيٍّ التوحيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالعبادةِ والتقوى."},"action":{"text":"اعبد اللهَ وحده واتّقه، فذاك دينُ الأنبياء جميعًا من نوحٍ إلى محمد."}},{"n":66,"reflection":{"text":"«قال الملأ الذين كفروا من قومه إنا لنراك في سفاهة وإنا لنظنك من الكاذبين» — قال كبراءُ قومه الكافرون: إنّا لنراك في خفّةِ عقلٍ وحمق، ونظنّك كاذبًا فيما تدّعيه من الرسالة؛ فرمَوه بالسفه والكذب؛ عادةُ المكذّبين رميُ الأنبياء بالعيوب. فالمترفون يصفون الناصحَ بالسفه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على وصفِ أهلِ الباطلِ للحقّ بالسفه."},"action":{"text":"لا يهزّك وصفُ المبطلين لك بالسفه أو الكذب حين تدعو للحقّ، فتلك سنّةٌ معهم."}},{"n":67,"reflection":{"text":"«قال يا قوم ليس بي سفاهة ولكني رسول من رب العالمين» — أجاب هودٌ بحلم: يا قوم لست سفيهًا كما زعمتم، بل أنا رسولٌ من ربّ العالمين؛ فردّ التهمةَ بالحقّ بلا انفعال؛ كما فعل نوحٌ من قبله. فالأنبياءُ يقابلون الأذى بالحلم والبيان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مقابلةُ الأذى بالحلمِ وثباتِ اليقين."},"action":{"text":"قابِل من يؤذيك في الحقّ بالحلم وثباتِ اليقين، فأنت على بيّنةٍ من ربّك."}},{"n":68,"reflection":{"text":"«أبلغكم رسالات ربي وأنا لكم ناصح أمين» — أبلّغكم ما أُرسلت به، وأنا لكم ناصحٌ أريد خيركم، أمينٌ على الوحي لا أزيد فيه ولا أنقص؛ فوصف نفسه بالنصح والأمانة، وهما صفتا كلِّ داعٍ صادق. فالنصحُ والأمانةُ ركنا الدعوة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التحلّي بالنصحِ للخلقِ والأمانةِ في التبليغ."},"action":{"text":"كن ناصحًا أمينًا فيما تبلّغه من الحقّ، لا تكتم منه شيئًا ولا تزد."}},{"n":69,"reflection":{"text":"«أوعجبتم أن جاءكم ذكر من ربكم على رجل منكم لينذركم واذكروا إذ جعلكم خلفاء من بعد قوم نوح وزادكم في الخلق بسطة فاذكروا آلاء الله لعلكم تفلحون» — أتعجبون أن يأتيكم تذكيرٌ على رجلٍ منكم لينذركم؟ واذكروا نعمةَ الله إذ جعلكم خلفاءَ في الأرض بعد قوم نوح، وزادكم قوّةً في الأجسام وبسطةً في الخلق؛ فاذكروا نعمَ الله لتشكروها فتفلحوا. فذكرُ نعم الله يقود إلى شكرها والفلاح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ نعمِ الله وشكرُها سبيلَ الفلاح."},"action":{"text":"تذكّر نعمَ الله عليك من القوّة والتمكين، واشكرها بالطاعة لتفلح."}},{"n":70,"reflection":{"text":"«قالوا أجئتنا لنعبد الله وحده ونذر ما كان يعبد آباؤنا فأتنا بما تعدنا إن كنت من الصادقين» — قالوا منكرين: أجئتنا لنُفرد الله بالعبادة ونترك آلهةَ آبائنا؟ فتمسّكوا بتقليد الآباء، وتحدّوه أن يأتيهم بالعذاب الذي يعدهم إن كان صادقًا؛ فاستعجلوا العذابَ استهزاءً. فالتقليدُ الأعمى والاستهزاءُ بالوعيد من صفات المكذّبين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ التقليدِ الأعمى وتعظيمُ التوحيد."},"action":{"text":"لا تتمسّك بباطل الآباء في مقابل التوحيد، ولا تستهزئ بوعيد الله."}},{"n":71,"reflection":{"text":"«قال قد وقع عليكم من ربكم رجس وغضب أتجادلونني في أسماء سميتموها أنتم وآباؤكم ما نزل الله بها من سلطان فانتظروا إني معكم من المنتظرين» — قال هودٌ: قد حقّ عليكم عذابٌ وغضبٌ من ربّكم؛ أتجادلونني في أصنامٍ ما هي إلا أسماءٌ سمّيتموها أنتم وآباؤكم بلا حجّةٍ من الله؟ فانتظروا العذابَ، إنّي معكم من المنتظرين لعاقبة الأمر؛ فبيّن أنّ آلهتهم أسماءٌ فارغةٌ لا حقيقةَ لها. فالمعبوداتُ الباطلةُ أسماءٌ بلا حقيقةٍ ولا سلطان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ المعبوداتِ الباطلةَ أسماءٌ بلا حقيقة."},"action":{"text":"لا تعبد ما لا حقيقةَ له، فآلهةُ الباطل أسماءٌ سمّاها الناسُ بلا برهانٍ من الله."}},{"n":72,"reflection":{"text":"«فأنجيناه والذين معه برحمة منا وقطعنا دابر الذين كذبوا بآياتنا وما كانوا مؤمنين» — فأنجينا هودًا ومن آمن معه برحمةٍ منّا، واستأصلنا آخرَ المكذّبين بالريح العقيم حتى لم يبقَ منهم أحد؛ وما كانوا مؤمنين فاستحقّوا الهلاك؛ فكانت النجاةُ برحمة الله والهلاكُ بالتكذيب. فرحمةُ الله تُنجي المؤمنين، والتكذيبُ يستأصل المكذّبين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في رحمةِ الله المنجيةِ للمؤمنين."},"action":{"text":"التمس رحمةَ الله بالإيمان والعمل، فبها نجا المؤمنون، وبالتكذيب هلك المعاندون."}}]},{"title":"قصّةُ صالحٍ وثمود: ناقةُ الله","range":[73,79],"theme":"دعوةُ صالحٍ للتوحيد، وآيةُ الناقة، وعقرُها عتوًّا فحلّ العذاب","verses":[{"n":73,"reflection":{"text":"«وإلى ثمود أخاهم صالحا قال يا قوم اعبدوا الله ما لكم من إله غيره قد جاءتكم بينة من ربكم هذه ناقة الله لكم آية فذروها تأكل في أرض الله ولا تمسوها بسوء فيأخذكم عذاب أليم» — وأرسلنا إلى ثمودَ أخاهم صالحًا فدعاهم إلى التوحيد، وجاءهم بمعجزةٍ طلبوها: ناقةٌ أخرجها الله من صخرة، جعلها آيةً؛ فأمرهم أن يتركوها ترعى في أرض الله ولا يؤذوها فيحلّ بهم العذاب. فالآياتُ تُقيم الحجّة، والاعتداءُ عليها يجلب العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ آياتِ الله وعدمُ الاعتداءِ عليها."},"action":{"text":"عظّم آياتِ الله وشعائرَه، ولا تعتدِ على حدوده، فالاعتداءُ عليها موجبٌ للعذاب."}},{"n":74,"reflection":{"text":"«واذكروا إذ جعلكم خلفاء من بعد عاد وبوأكم في الأرض تتخذون من سهولها قصورا وتنحتون الجبال بيوتا فاذكروا آلاء الله ولا تعثوا في الأرض مفسدين» — واذكروا نعمةَ الله إذ جعلكم خلفاءَ بعد عادٍ، ومكّنكم في الأرض تبنون في السهول القصورَ وتنحتون في الجبال البيوت؛ فاذكروا نعمَه بالشكر، ولا تفسدوا في الأرض بالمعاصي والشرك؛ فالنعمةُ تستوجب الشكرَ لا الفساد. فمقابلةُ النعمةِ بالفسادِ كفرٌ لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ التمكينِ وتركُ الفسادِ في الأرض."},"action":{"text":"اشكر نعمةَ الله عليك في القوّة والتمكين بالطاعة، ولا تُفسد في الأرض."}},{"n":75,"reflection":{"text":"«قال الملأ الذين استكبروا من قومه للذين استضعفوا لمن آمن منهم أتعلمون أن صالحا مرسل من ربه قالوا إنا بما أرسل به مؤمنون» — قال المتكبّرون من قوم صالح للضعفاء الذين آمنوا مستهزئين: أتعلمون حقًّا أنّ صالحًا رسولٌ من ربّه؟ فأجاب المؤمنون بيقينٍ وثبات: إنّا بما أُرسل به مؤمنون؛ فثبات الضعفاء على الحقّ أمام استكبار الكبراء. فالإيمانُ يثبّت الضعيفَ أمام استهزاء المتكبّرين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الإيمانِ أمامَ استهزاءِ المتكبّرين."},"action":{"text":"اثبت على إيمانك ولو استضعفك المتكبّرون واستهزؤوا بك، فاليقينُ عزّة."}},{"n":76,"reflection":{"text":"«قال الذين استكبروا إنا بالذي آمنتم به كافرون» — قال المتكبّرون بعنادٍ: إنّا بالذي آمنتم به كافرون؛ فأعلنوا كفرهم كبرًا وعنادًا؛ فالكبرُ يمنع صاحبَه من قبول الحقّ ولو تبيّن. فالكبرُ حاجبٌ عن الإيمان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الكبرِ الحاجبِ عن قبولِ الحقّ."},"action":{"text":"احذر الكبرَ فهو يمنعك من قبول الحقّ ولو وضح، كما منع المتكبّرين من ثمود."}},{"n":77,"reflection":{"text":"«فعقروا الناقة وعتوا عن أمر ربهم وقالوا يا صالح ائتنا بما تعدنا إن كنت من المرسلين» — فقتلوا الناقةَ متجاوزين أمرَ ربّهم متعالين، وتحدّوا صالحًا أن يأتيهم بالعذاب إن كان رسولًا؛ فبلغ بهم العتوُّ استعجالَ العذاب استهزاءً. فالعتوُّ عن أمر الله واستعجالُ العذابِ من صفات الهالكين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من العتوِّ عن أمرِ اللهِ واستعجالِ عذابه."},"action":{"text":"لا تتجاوز حدودَ الله متعاليًا، ولا تستعجل وعيدَه استهزاءً، فتلك سبيلُ الهلاك."}},{"n":78,"reflection":{"text":"«فأخذتهم الرجفة فأصبحوا في دارهم جاثمين» — فأخذتهم الصيحةُ والزلزلةُ الشديدة، فأصبحوا في ديارهم موتى هامدين على ركبهم لا حراكَ بهم؛ فحلّ بهم العذابُ الذي استعجلوه. فعاقبةُ العتوِّ هلاكٌ في لحظة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بسرعةِ حلولِ العذابِ بالمعاندين."},"action":{"text":"اعتبر بمصارع المعاندين، فقد أصبحوا بعد عتوّهم موتى جاثمين في ديارهم."}},{"n":79,"reflection":{"text":"«فتولى عنهم وقال يا قوم لقد أبلغتكم رسالة ربي ونصحت لكم ولكن لا تحبون الناصحين» — فأعرض صالحٌ عن قومه بعد هلاكهم وقال متحسّرًا: لقد بلّغتكم رسالةَ ربّي ونصحتُ لكم غايةَ النصح، ولكنّكم لا تحبّون من ينصحكم؛ فكان تكذيبُهم لكراهتهم الناصحين لا لخفاء الحقّ. فكراهةُ النصحِ سببُ ردّ الحقّ والهلاك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محبّةُ النصحِ وقبولُه ممن يبتغي الخير."},"action":{"text":"أحبِب من ينصحك بالحقّ واقبل نصحه، فكراهةُ الناصحين أهلكت الأمم."}}]},{"title":"قصّةُ لوطٍ: أوّلُ من أتى الفاحشة","range":[80,84],"theme":"إنكارُ لوطٍ فاحشةً لم تُسبَق، وطردُ قومه له، وإهلاكُهم بالمطر","verses":[{"n":80,"reflection":{"text":"«ولوطا إذ قال لقومه أتأتون الفاحشة ما سبقكم بها من أحد من العالمين» — وأرسلنا لوطًا إذ قال لقومه منكرًا: أتفعلون الفاحشةَ الشنيعة (إتيانَ الرجال) التي ما سبقكم إليها أحدٌ من العالمين؟ فابتدعوا شرًّا لم يُعرف قبلهم؛ فبيّن قبحَها بأنّها بدعةٌ في الشرّ. فبعضُ المعاصي جرأةٌ على ابتداعِ شرٍّ جديد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استقباحُ الفاحشةِ وإنكارُها بالحكمة."},"action":{"text":"أنكِر المنكرَ الشنيعَ وبيّن قبحَه، ولا تألف ما استقبحته الفطرُ والشرائع."}},{"n":81,"reflection":{"text":"«إنكم لتأتون الرجال شهوة من دون النساء بل أنتم قوم مسرفون» — إنّكم تقضون الشهوةَ مع الرجال تاركين ما خلق الله لكم من النساء؛ بل أنتم قومٌ متجاوزون حدودَ الله والفطرة؛ فوصفهم بالإسراف لخروجهم عن الفطرة السويّة. فمخالفةُ الفطرةِ إسرافٌ وتجاوز.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ الفطرةِ السويّةِ وتوقّي مخالفتها."},"action":{"text":"الزم ما خلقك الله عليه من الفطرة، فمخالفتُها إسرافٌ وخروجٌ عن حدود الله."}},{"n":82,"reflection":{"text":"«وما كان جواب قومه إلا أن قالوا أخرجوهم من قريتكم إنهم أناس يتطهرون» — وما كان جوابُ قوم لوطٍ على نصحه إلا أن قالوا: أخرجوا لوطًا وأتباعه من قريتكم، ساخرين: إنّهم أناسٌ يتنزّهون عن أفعالنا! فجعلوا الطهارةَ عيبًا يُطرَد به أصحابُها؛ فانتكست فطرتُهم حتى عابوا الفضيلة. فحين تنتكس الفطرةُ يصير المعروفُ منكرًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتزازُ بالطهارةِ والعفّةِ ولو عابها المنتكسون."},"action":{"text":"اعتزّ بطهارتك وعفّتك، ولا يضرّك أن يعيبها أهلُ الفساد، فالعيبُ عليهم."}},{"n":83,"reflection":{"text":"«فأنجيناه وأهله إلا امرأته كانت من الغابرين» — فأنجينا لوطًا وأهله المؤمنين إلا امرأتَه فكانت من الباقين في العذاب لكفرها وخيانتها؛ فلم تنفعها زوجيّةُ النبيّ مع كفرها؛ فالنجاةُ بالإيمان لا بالنسب. فقرابةُ الصالحين لا تنفع مع الكفر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ النجاةَ بالإيمانِ لا بالقرابة."},"action":{"text":"اطلب النجاةَ بإيمانك وعملك، فلا تنفع قرابةُ صالحٍ مع كفرٍ كامرأة لوط."}},{"n":84,"reflection":{"text":"«وأمطرنا عليهم مطرا فانظر كيف كان عاقبة المجرمين» — وأمطرنا على قوم لوطٍ حجارةً من سجّيل بعد أن قلبنا قريتهم؛ فانظر كيف كانت عاقبةُ المجرمين المصرّين؛ فتأمّل في مصارعهم للعبرة. فعاقبةُ الإجرامِ والإصرارِ هلاكٌ وخزي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ المجرمينَ المصرّين."},"action":{"text":"تأمّل عاقبةَ المجرمين، واحذر أن تُصرّ على فاحشةٍ أو منكر، فعاقبتُه الهلاك."}}]},{"title":"قصّةُ شعيبٍ ومدين: التوحيدُ والعدلُ في المعاملة","range":[85,93],"theme":"دعوةُ شعيبٍ للتوحيد وإيفاءِ الكيل، وتهديدُ الملأ، وثباتُ شعيبٍ وتوكّلُه، وهلاكُ المكذّبين","verses":[{"n":85,"reflection":{"text":"«وإلى مدين أخاهم شعيبا قال يا قوم اعبدوا الله ما لكم من إله غيره قد جاءتكم بينة من ربكم فأوفوا الكيل والميزان ولا تبخسوا الناس أشياءهم ولا تفسدوا في الأرض بعد إصلاحها ذلكم خير لكم إن كنتم مؤمنين» — وأرسلنا إلى أهل مدينَ أخاهم شعيبًا، فدعاهم إلى التوحيد أوّلًا، ثمّ نهاهم عن دائهم: تطفيفِ الكيل والميزان وبخسِ الناس حقوقهم والإفساد في الأرض؛ وبيّن أنّ الوفاءَ خيرٌ لهم إن كانوا مؤمنين؛ فقرن إصلاحَ العقيدة بإصلاح المعاملة. فالإيمانُ يُصلح العقيدةَ والمعاملةَ معًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين توحيدِ الله والعدلِ في المعاملة."},"action":{"text":"وحّد الله وأوفِ الكيلَ والوزن، ولا تبخس الناسَ حقوقهم، فالإيمانُ يُصلح المعاملة."}},{"n":86,"reflection":{"text":"«ولا تقعدوا بكل صراط توعدون وتصدون عن سبيل الله من آمن به وتبغونها عوجا واذكروا إذ كنتم قليلا فكثركم وانظروا كيف كان عاقبة المفسدين» — ولا تجلسوا على الطرق تُخوّفون الناسَ وتصدّونهم عن دين الله وتطلبون له الاعوجاج؛ واذكروا نعمةَ الله إذ كنتم قليلًا فكثّركم؛ واعتبروا بعاقبة المفسدين قبلكم؛ فنهاهم عن الصدّ وذكّرهم بالنعمة والعبرة. فالصدُّ عن سبيل الله وقطعُ الطريق من أعظم الفساد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الصدِّ عن سبيل الله وتذكّرُ نعمِه."},"action":{"text":"لا تصدّ أحدًا عن الحقّ ولا ترهبه، واذكر نعمَ الله عليك، واعتبر بعاقبة المفسدين."}},{"n":87,"reflection":{"text":"«وإن كان طائفة منكم آمنوا بالذي أرسلت به وطائفة لم يؤمنوا فاصبروا حتى يحكم الله بيننا وهو خير الحاكمين» — وإن انقسمتم فريقين: مؤمنٌ بما أُرسلت به وكافر، فاصبروا واتركوا الأمرَ حتى يفصل الله بيننا بحكمه العدل، وهو خيرُ من يحكم؛ فوكّل الأمرَ إلى الله بثقةٍ. فالصبرُ وانتظارُ حكمِ الله ثقةٌ بعدله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["خير الحاكمين"],"heart_state":{"text":"الصبرُ وتفويضُ الحكمِ إلى الله خيرِ الحاكمين."},"action":{"text":"اصبر على المخالف، وكِل الحكمَ إلى الله، فهو خيرُ الحاكمين يفصل بالعدل."}},{"n":88,"reflection":{"text":"«قال الملأ الذين استكبروا من قومه لنخرجنك يا شعيب والذين آمنوا معك من قريتنا أو لتعودن في ملتنا قال أولو كنا كارهين» — هدّد المتكبّرون شعيبًا والمؤمنين معه بالإخراج من البلد أو العودة إلى دينهم الباطل؛ فأجابهم شعيبٌ منكرًا: أتُكرهوننا على العودة ولو كنّا كارهين لدينكم؟ فلا إكراهَ يردّ المؤمنَ إلى الكفر بعد إذ هداه الله. فالمؤمنُ لا يعود إلى الباطل ولو هُدّد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الإيمانِ ورفضُ الإكراهِ على الباطل."},"action":{"text":"اثبت على دينك ولو هُدّدت بالإخراج، ولا ترجع إلى باطلٍ نجّاك الله منه."}},{"n":89,"reflection":{"text":"«قد افترينا على الله كذبا إن عدنا في ملتكم بعد إذ نجانا الله منها وما يكون لنا أن نعود فيها إلا أن يشاء الله ربنا وسع ربنا كل شيء علما على الله توكلنا ربنا افتح بيننا وبين قومنا بالحق وأنت خير الفاتحين» — قال شعيبٌ ومن معه: لو عدنا إلى دينكم بعد أن نجّانا الله منه لكنّا مفترين على الله كذبًا؛ ولا يمكن أن نعود إليه إلا أن يشاء الله (وهو لا يشاء لنا الشرّ)؛ وسع علمُ ربّنا كلَّ شيء، وعليه توكّلنا؛ ثمّ دعوا: ربّنا افصل بيننا وبين قومنا بالحقّ وأنت خيرُ الفاتحين؛ فجمعوا الثباتَ والتوكّلَ والدعاء. فالمؤمنُ يثبت متوكّلًا ويفوّض الحكمَ لله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["خير الفاتحين"],"heart_state":{"text":"الثباتُ مع التوكّلِ على الله وتفويضِ الحكمِ إليه."},"action":{"text":"اثبت على الحقّ متوكّلًا على الله، وادعُه أن يفصل بينك وبين مخالفيك بالحقّ."}},{"n":90,"reflection":{"text":"«وقال الملأ الذين كفروا من قومه لئن اتبعتم شعيبا إنكم إذا لخاسرون» — وقال الكبراءُ الكافرون محذّرين قومهم: لئن اتّبعتم شعيبًا وتركتم آلهتكم إنّكم إذًا لخاسرون تجارتكم ودنياكم؛ فخوّفوهم بالخسارة الدنيويّة ليصدّوهم عن الحقّ؛ فقلبوا الحقيقة، فالخسارةُ في اتّباع الباطل لا الحقّ. فأهلُ الباطلِ يخوّفون من اتّباع الحقّ بالخسارة، والخسارةُ في تركه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الانخداعِ بتخويفِ أهلِ الباطلِ من اتّباعِ الحقّ."},"action":{"text":"لا يصدّك تخويفُ الناس من خسارةٍ دنيويّةٍ عن اتّباع الحقّ، فالخسارةُ في تركه."}},{"n":91,"reflection":{"text":"«فأخذتهم الرجفة فأصبحوا في دارهم جاثمين» — فأخذت المكذّبين الزلزلةُ الشديدة (وفي موضعٍ آخر عذابُ يوم الظُّلّة)، فأصبحوا في ديارهم موتى هامدين على ركبهم؛ فحلّ العذابُ بمن كذّب وهدّد. فعاقبةُ التكذيبِ والتهديدِ للحقّ هلاك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ من كذّبَ الحقَّ وهدّدَ أهلَه."},"action":{"text":"اعتبر بمصير من كذّب الرسلَ وهدّد المؤمنين، فأخذتهم الرجفةُ فأصبحوا جاثمين."}},{"n":92,"reflection":{"text":"«الذين كذبوا شعيبا كأن لم يغنوا فيها الذين كذبوا شعيبا كانوا هم الخاسرين» — الذين كذّبوا شعيبًا صاروا كأنّهم لم يقيموا في ديارهم ولم يعيشوا فيها، أبادهم العذابُ فكأنّهم لم يكونوا؛ وهم — لا المؤمنون الذين خوّفوهم بالخسارة — الخاسرون حقًّا في الدنيا والآخرة؛ فانقلب زعمُهم عليهم. فالخاسرُ الحقيقيُّ هو المكذّب لا المؤمن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الخاسرَ الحقيقيَّ هو المكذّبُ للحقّ."},"action":{"text":"اعلم أنّ الخاسرَ من كذّب الحقّ لا من اتّبعه، فمصيرُ المكذّبين البوارُ والخسران."}},{"n":93,"reflection":{"text":"«فتولى عنهم وقال يا قوم لقد أبلغتكم رسالات ربي ونصحت لكم فكيف آسى على قوم كافرين» — فأعرض شعيبٌ عنهم بعد هلاكهم وقال: لقد بلّغتكم رسالاتِ ربّي ونصحتُ لكم غايةَ النصح فلم تقبلوا؛ فكيف أحزن على قومٍ كافرين اختاروا الهلاك بأنفسهم؟ فبعد أداء البلاغِ والنصح لا يبقى للداعي حزنٌ على المعاند. فمن أدّى ما عليه من البلاغ لم يحزن على من أبى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أداءُ البلاغِ والنصحِ وطرحُ الحزنِ على المعاندين."},"action":{"text":"بلّغ وانصح بصدق، ثمّ لا تحمل حزنًا على من أصرّ على الكفر بعد البيان."}}]}],"coverage":{"covered":93,"total":206}};
